import{af as t,z as o,J as a,ab as r}from"./chunks/framework.pGEaBvn1.js";const c=JSON.parse('{"title":"How to use the power budget feature on the LightBug Cloud","description":"","frontmatter":{"aside":false,"sidebar":false,"editLink":false},"headers":[],"relativePath":"guides/power-budget-cloud.md","filePath":"guides/power-budget-cloud.md"}'),i={name:"guides/power-budget-cloud.md"};function n(d,e,l,s,u,h){return o(),a("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793270749000"},[...e[0]||(e[0]=[r('<h1 id="how-to-use-the-power-budget-feature-on-the-lightbug-cloud" tabindex="-1">How to use the power budget feature on the LightBug Cloud <a class="header-anchor" href="#how-to-use-the-power-budget-feature-on-the-lightbug-cloud" aria-label="Permalink to &quot;How to use the power budget feature on the LightBug Cloud&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">ℹ️ Information</p><p>If you find that the battery of your device is draining too quickly, we recommend enabling the power budget feature.</p></div><h2 id="what-is-the-power-budget-feature" tabindex="-1">What is the power budget feature? <a class="header-anchor" href="#what-is-the-power-budget-feature" aria-label="Permalink to &quot;What is the power budget feature?&quot;">​</a></h2><p>This feature allows a certain amount of power to be used when <code>transmitting</code>, so if the conditions are not great, and the tracker has to use a lot of power to transmit, it will ignore the location update and try again later if the conditions are better.</p><p>Examples of where this will be useful are:</p><ol><li><p>In very low signal areas i.e. underground parking or rural areas</p></li><li><p>If the tracker is in a metal container i.e. delivery vehicle or cargo ship</p></li><li><p>For any other scenario where the tracker uses too much time for a single transmission</p></li></ol><h2 id="how-do-i-apply-the-power-budget-feature" tabindex="-1">How do I apply the power budget feature? <a class="header-anchor" href="#how-do-i-apply-the-power-budget-feature" aria-label="Permalink to &quot;How do I apply the power budget feature?&quot;">​</a></h2><ol><li><p>On the main page of the tracking portal, click the <code>orange circle</code> on the bottom left hand side, and then click <code>settings</code> (the black cog).<br><img src="" alt=""></p></li><li><p>A window will be appear like the one below. Go to <code>&#39;Power Budget&#39;</code> and enable the power budget feature so that the toggle is <code>orange</code>.<br><img src="" alt=""></p></li><li><p>After enabling power budgeting the <code>&#39;Budget Mode&#39;</code> option will appear. Upon pressing the drop down arrow, a box will appear, here you have to set your preferred mode.<br><img src="" alt=""></p></li></ol><p>The percentages show how many location updates <strong><em>might</em></strong> be dropped in average conditions.</p><ol start="4"><li>Review the settings and then select &#39;save&#39;.<br><img src="" alt=""></li></ol><div class="tip custom-block"><p class="custom-block-title">⚡ Tip</p><p>To apply the new settings immediately, press the button on your tracker. If you don&#39;t have your tracker to hand, the tracker will update its settings the next time it is scheduled to send a location update.</p></div><p>If you can&#39;t find the information you&#39;re looking for, <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">get in touch!</a></p>',12)])])}const g=t(i,[["render",n]]);export{c as __pageData,g as default};
